"""A small virtual body with three VIVE trackers, for testing the calibration without a headset.

Rigid pieces only: feet, pelvis, chest, head. World: +Y up, the person looks toward -Z, +X is her right.
Each tracker is glued to a body part at a chosen place and tilt, with sensor noise on top, so what the
calibration sees is what a real tracker would give. Nothing here knows the calibration code.
"""
import numpy as np

from fbtcal import body as B


def rot_x(a):
    c, s = np.cos(a), np.sin(a)
    return np.array([[1, 0, 0], [0, c, -s], [0, s, c]])


def rot_y(a):
    c, s = np.cos(a), np.sin(a)
    return np.array([[c, 0, s], [0, 1, 0], [-s, 0, c]])


def rot_z(a):
    c, s = np.cos(a), np.sin(a)
    return np.array([[c, -s, 0], [s, c, 0], [0, 0, 1]])


def mat_q(r):
    return B.mat_to_pose(np.hstack([r, np.zeros((3, 1))]))[1]


def q_mat(q):
    return B.pose_to_mat(np.zeros(3), q)[:, :3]


class Body:
    """Her body at rest, standing straight. Sizes in metres."""

    def __init__(self, eye=1.54, pelvis_behind_neck=0.0, waist_mount=(0.16, 0.05, -0.02), waist_tilt_deg=(8, 0, 6),
                 noise_mm=1.0, noise_deg=0.1, seed=0):
        self.eye = eye
        self.rng = np.random.default_rng(seed)
        self.noise_m, self.noise_rad = noise_mm * 1e-3, np.radians(noise_deg)
        # joints at rest (x right, y up, z back): the spine axis is x=0, z=0; the neck pivot is
        # 0.11 under and 0.08 behind the eyes (the same numbers the calibration assumes)
        self.neck0 = np.array([0.0, eye - B.NECK_UP, 0.0])
        self.pelvis0 = np.array([0.0, 0.56 * eye, pelvis_behind_neck])  # the true turning point of the hips
        self.chest0 = self.pelvis0 + np.array([0.0, 0.30, 0.0])
        self.ankle0 = (np.array([-0.06, 0.075, 0.0]), np.array([0.06, 0.075, 0.0]))
        self.eye_off = np.array([0.0, B.NECK_UP, -B.NECK_FWD])  # from the neck pivot to the eyes, head level
        # trackers: place in the part's frame + tilt. The sensor side (-Z of the tracker) faces outward.
        out = np.array([1.0, 0.0, 0.0])  # the belt tracker sits on her right side
        self.waist_pos = np.asarray(waist_mount, float)  # from the pelvis centre
        tilt = rot_x(np.radians(waist_tilt_deg[0])) @ rot_y(np.radians(waist_tilt_deg[1])) @ rot_z(np.radians(waist_tilt_deg[2]))
        # tracker axes in the pelvis frame: top toward +X (outward), up along Y, x toward the back
        base = np.column_stack([[0, 0, 1], [0, 1, 0], [-1, 0, 0]])
        self.waist_rot = tilt @ base
        # feet: on the instep, sensor side up (-Z of the tracker = world up), toes toward -Z_world
        foot_base = np.column_stack([[1, 0, 0], [0, 0, -1], [0, 1, 0]])
        self.foot_pos = np.array([0.0, 0.10, -0.04])
        self.foot_rot = foot_base

    # ---- the body in a pose ----
    def pose(self, yaw=0.0, pitch=0.0, roll=0.0, move=(0, 0, 0), chest_follow=0.4, head_yaw=0.0, head_pitch=0.0):
        """Body parts for one pose. yaw/pitch/roll turn the pelvis about its centre; the chest follows
        the pelvis yaw by `chest_follow`; the head turns on its own (looking where she wants)."""
        move = np.asarray(move, float)
        rp = rot_y(yaw) @ rot_x(pitch) @ rot_z(roll)
        pelvis = self.pelvis0 + move
        rc = rot_y(chest_follow * yaw) @ rot_x(0.6 * pitch)
        chest = pelvis + rp @ (self.chest0 - self.pelvis0)
        neck = chest + rc @ (self.neck0 - self.chest0)
        rh = rot_y(head_yaw) @ rot_x(head_pitch)
        eyes = neck + rh @ self.eye_off
        return {"R_pelvis": rp, "pelvis": pelvis, "chest": chest, "neck": neck, "R_head": rh, "eyes": eyes,
                "ankles": tuple(a + move * np.array([1, 0, 1]) * 0 for a in self.ankle0)}

    def noisy(self, pos, rot):
        p = pos + self.rng.normal(0, self.noise_m, 3)
        d = self.rng.normal(0, self.noise_rad, 3)
        r = rot_x(d[0]) @ rot_y(d[1]) @ rot_z(d[2]) @ rot
        return p, mat_q(r)

    def trackers(self, st):
        """Real poses (pos, quat w x y z) the trackers would report in this body state."""
        rp, pel = st["R_pelvis"], st["pelvis"]
        waist = self.noisy(pel + rp @ self.waist_pos, rp @ self.waist_rot)
        feet = []
        for a in st["ankles"]:
            feet.append(self.noisy(a + self.foot_pos, self.foot_rot))
        return {"waist": waist, "left_foot": feet[0], "right_foot": feet[1]}

    def head(self, st):
        return self.noisy(st["eyes"], st["R_head"])[0], mat_q(st["R_head"])
